  {"id": "krasne", "cat": "settle", "lat": 51.448, "lng": 30.003, "p": "est", "acc": "±2 km", "z": 12, "en": "Krasne", "ru": "Красное", "d": "Village north-west of Pripyat on the river, inside the northern trace.", "src": "Position estimated"},
  {"id": "zal", "cat": "settle", "lat": 51.25296, "lng": 30.19278, "p": "map", "acc": "±150 m", "z": 12, "en": "Zalissia", "ru": "Залесье", "d": "Large village on the road south of Chernobyl, a regular stop on pre-war tours.", "src": "Kyiv Post (tour route); position estimated"},
  {"id": "opach", "cat": "settle", "lat": 51.19993, "lng": 30.32782, "p": "map", "acc": "±150 m", "z": 12, "en": "Opachychi", "ru": "Опачичи", "d": "Village on the Pripyat south of Chernobyl, one of the places where elderly self-settlers (самоселы) returned.", "src": "Position estimated"},
  {"id": "parysh", "cat": "settle", "lat": 51.28447, "lng": 30.32553, "p": "map", "acc": "±150 m", "z": 12, "en": "Paryshiv", "ru": "Парышев", "d": "Left-bank village with a zone checkpoint; a few self-settlers lived here after 1986.", "src": "Position estimated"},
  {"id": "ch2", "cat": "mil", "lat": 51.30307, "lng": 30.07605, "p": "map", "acc": "±150 m", "z": 12, "en": "Chernobyl-2 garrison town", "ru": "«Чернобыль-2» (в/ч)", "d": "Closed military town for the radar crews, with barracks, school, shop and command bunker. Disguised on maps and road signs as a children's summer camp. The General Staff sheets print «пионерлагерь (недейств.)» on this spot.", "src": "Position read from sheet M-36-25 (1993)"},
  {"id": "duga", "cat": "mil", "lat": 51.30529, "lng": 30.06593, "p": "pub", "z": 10, "lc": "plant", "en": "Duga-1 receiver array", "ru": "ЗГРЛС «Дуга-1» (приёмный центр)", "d": "Over-the-horizon radar of the Soviet missile early-warning network, nicknamed the «Russian Woodpecker» for the tapping it broadcast across the shortwave bands. The main array is about 700 m long and 150 m high, with a smaller high-band array beside it. Operated 1976–1989. On the General Staff sheets the site is labelled «пионерлагерь (недейств.)», an inactive pioneer camp: the cover story was printed on secret military maps too.", "src": "Wikipedia; sheets M-36-25 (1993) and M-36-13", "wiki": "https://en.wikipedia.org/wiki/Duga_radar"},
  {"id": "lyub", "cat": "mil", "lat": 51.63777, "lng": 30.70289, "p": "pub", "z": 10, "en": "Liubech-1 transmitter site", "ru": "Передающий центр «Любеч-1»", "d": "The radar's transmitters, about 60 km north-east of the receiver. Little remains above ground.", "src": "Wikipedia", "wiki": "https://en.wikipedia.org/wiki/Duga_radar"},
  {"id": "rass", "cat": "liq", "lat": 51.15975, "lng": 29.97763, "p": "map", "acc": "±150 m", "z": 11, "en": "Rassokha vehicle graveyard", "ru": "Могильник техники «Рассоха»", "d": "The largest holding yard for contaminated liquidation equipment: Mi-6 and Mi-8 helicopters, trucks, buses, fire engines, APCs and engineering vehicles. Looted for scrap through the 1990s and 2000s. The yard was closed in late 2012: vehicles that could be decontaminated were cut up for scrap, and the most contaminated helicopters and engineering vehicles were moved to the Buriakivka disposal site. Little of the famous rows remains. The marker sits on Rassokha village as drawn on sheet M-35-36 (population 600 in 1986); the yard itself is not on the map.", "src": "wearethemighty.com; Telegraf (Jan 2026); Domkovych & Tarnavskyi (Lviv State University of Life Safety); sheet M-35-36 (1986)"},
  {"id": "redf", "cat": "liq", "lat": 51.38011, "lng": 30.04908, "p": "pub", "z": 12, "en": "Red Forest", "ru": "Рыжий лес", "d": "About 10 km² of pine forest west of the plant that turned red-brown and died from the 1986 fallout. Crews bulldozed the trees into trenches, covered them with sand and replanted. Fires burned here in 2015 and 2020. Russian troops dug trenches in it in 2022.", "src": "Wikipedia", "wiki": "https://en.wikipedia.org/wiki/Red_Forest"},
  {"id": "decon", "cat": "liq", "lat": 51.29993, "lng": 30.17218, "p": "map", "acc": "±150 m", "z": 13, "en": "Leliv decontamination post", "ru": "Пункт спецобработки «Лелёв»", "d": "Vehicle wash and dosimetric control post on the road out of the 10-km zone, used since 1986. The 1993 Chernobyl sheet marks it «автомобильная мойка» (vehicle wash), one of two on that sheet.", "src": "Sheet M-36-25 (1993)"},
  {"id": "wormwood", "cat": "mem", "lat": 51.274, "lng": 30.2324, "p": "est", "acc": "±400 m", "z": 13, "en": "«Wormwood Star» memorial park", "ru": "Мемориал «Звезда Полынь»", "d": "Opened in Chernobyl town for the 25th anniversary (2011). An alley of name signs remembers the evacuated villages, and a metal angel sounds a trumpet.", "src": "Published accounts; position estimated"},
  {"id": "firemon", "cat": "mem", "lat": 51.2783, "lng": 30.2234, "p": "est", "acc": "±400 m", "z": 13, "en": "Firefighters' monument «To those who saved the world»", "ru": "Памятник «Тем, кто спас мир»", "d": "Raised by the Chernobyl fire station by the liquidators themselves for the 20th anniversary in 2006.", "src": "Published accounts; position estimated"},
  {"id": "ilya", "cat": "mem", "lat": 51.2798, "lng": 30.2269, "p": "est", "acc": "±400 m", "z": 14, "en": "St Elijah's church", "ru": "Ильинская церковь", "d": "Wooden church in Chernobyl town that kept holding services after 1986.", "src": "Position estimated"},
  {"id": "port-ch", "cat": "mem", "lat": 51.2843, "lng": 30.2464, "p": "est", "acc": "±500 m", "z": 14, "en": "Chernobyl river port", "ru": "Чернобыльский порт", "d": "Riverside quay where the barges and tugs used in the 1986 river work were left to rust.", "src": "Position estimated"},
  {"id": "kpp-dyt", "cat": "check", "lat": 51.119, "lng": 30.147, "p": "est", "acc": "±500 m", "z": 11, "en": "Dytiatky checkpoint (30-km zone)", "ru": "КПП «Дитятки»", "d": "Main southern entry from the Kyiv road, the gate used by most pre-2022 visitors.", "src": "Wikipedia", "wiki": "https://en.wikipedia.org/wiki/Dytiatky"},
  {"id": "kpp-lel", "cat": "check", "lat": 51.29663, "lng": 30.18087, "p": "map", "acc": "±150 m", "z": 11, "en": "Leliv checkpoint (10-km zone)", "ru": "КПП «Лелёв»", "d": "Inner checkpoint on the road to the plant; vehicles and people are checked on the way out.", "src": "Position estimated"},
  {"id": "kpp-par", "cat": "check", "lat": 51.308, "lng": 30.27, "p": "est", "acc": "±3 km", "z": 11, "en": "Paryshiv checkpoint", "ru": "КПП «Парышев»", "d": "Checkpoint on the left bank of the Pripyat.", "src": "Position estimated"},
  {"id": "h-redf", "cat": "hot", "lat": 51.379, "lng": 30.042, "p": "est", "acc": "area", "z": 11, "en": "Red Forest burial trenches", "ru": "Захоронения Рыжего леса", "d": "Highest ground contamination outside the plant fence. Fuel-particle fallout from the first explosion fell here in a narrow band.", "src": "Kashparov et al. 2018; Wikipedia", "wiki": "https://en.wikipedia.org/wiki/Red_Forest"},
  {"id": "h-hosp", "cat": "hot", "lat": 51.4013, "lng": 30.0488, "p": "est", "acc": "±200 m", "z": 14, "en": "Hospital 126 basement", "ru": "Подвал МСЧ-126", "d": "Firefighters' clothing from 26 April. Indoor hotspot, off limits.", "src": "Published accounts"},
  {"id": "h-yan", "cat": "hot", "lat": 51.3925, "lng": 30.079, "p": "est", "acc": "area", "z": 12, "en": "Yaniv station area", "ru": "Район ст. Янов", "d": "Ground near the station and the road to the plant took heavy early fallout.", "src": "Published accounts"},
  {"id": "h-pond", "cat": "hot", "lat": 51.35, "lng": 30.17, "p": "est", "acc": "area", "z": 12, "en": "Exposed cooling-pond sediments", "ru": "Обсохшее дно пруда-охладителя", "d": "Caesium- and strontium-bearing sediments left dry as the pond level falls.", "src": "Wikipedia", "wiki": "https://en.wikipedia.org/wiki/Chernobyl_Nuclear_Power_Plant"},
  {"id": "w-occ", "cat": "war", "lat": 51.393, "lng": 30.093, "p": "est", "acc": "marker", "z": 11, "en": "Occupation of the plant, 24 Feb – 31 Mar 2022", "ru": "Оккупация ЧАЭС", "d": "Russian forces entering from Belarus took the plant on the first day of the invasion. The shift on duty was kept at work for weeks without rotation. Troops withdrew on 31 March 2022.", "src": "IAEA and press reports"},
  {"id": "w-drone", "cat": "war", "lat": 51.3888, "lng": 30.1, "p": "est", "acc": "marker", "z": 13, "en": "Drone strike on the NSC, 14 Feb 2025", "ru": "Удар дрона по НБК", "d": "Hit the arch's roof and started a long fire in its insulation. See the Unit 4 entry for repair status.", "src": "ASNR 2026"},
  {"id": "w-redf", "cat": "war", "lat": 51.383, "lng": 30.056, "p": "est", "acc": "area", "z": 12, "en": "Trenches in the Red Forest, 2022", "ru": "Окопы в Рыжем лесу", "d": "Russian troops dug positions in contaminated soil. Reports of radiation sickness were never confirmed; the IAEA estimated modest doses.", "src": "Wikipedia; IAEA", "wiki": "https://en.wikipedia.org/wiki/Red_Forest"},
  {"id": "n-reserve", "cat": "nature", "lat": 51.24, "lng": 29.8, "p": "est", "acc": "area label", "z": 10, "en": "Chornobyl Radiation and Ecological Biosphere Reserve", "ru": "Радиационно-экологический биосферный заповедник", "d": "Created in 2016 over about 2,270 km² of the Ukrainian zone. Wolves, elk, lynx, bison and boar live here in numbers well above the surrounding region.", "src": "Published accounts"},
  {"id": "n-horse", "cat": "nature", "lat": 51.315, "lng": 29.87, "p": "est", "acc": "area", "z": 11, "en": "Przewalski's horses", "ru": "Лошади Пржевальского", "d": "About 30 were released in 1998 as an experiment; the herd has grown and ranges across the western zone and into Belarus.", "src": "Published accounts"},
  {"id": "n-psrer", "cat": "nature", "lat": 51.62, "lng": 29.95, "p": "est", "acc": "area label", "z": 10, "en": "Polesie State Radioecological Reserve (Belarus)", "ru": "Полесский радиационно-экологический заповедник", "d": "Belarus's half of the zone, about 2,160 km², set up in 1988 north of the border.", "src": "Published accounts"}
